import{_ as n}from"./chunks/0.1.60-rules-test-193.BIxiAEmj.js";import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/rules.md","filePath":"projects/logic-studio/user-guide/rules.md","lastUpdated":1794767865000}'),r={name:"projects/logic-studio/user-guide/rules.md"};function u(l,e,d,o,h,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Lege eine Regel an und öffne den Assistenten. Wähle <strong>Zustand</strong>, deinen Testhelfer und als neuen Wert <code>on</code>. Füge unter <strong>DANN</strong> eine Aktion für einen zweiten Helfer hinzu. Exportiere die Regel als HA-YAML und prüfe sie in Home Assistant.</p><p>So sieht der Rules-Editor mit der Auswahl links und den Abschnitten FALLS, DANN und SONST aus.</p><p><img src="'+n+'" alt="Rules-Editor mit Auslösern, Bedingungen und Aktionszweigen"></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="assistent-und-palette" tabindex="-1">Assistent und Palette <a class="header-anchor" href="#assistent-und-palette" aria-label="Permalink to &quot;Assistent und Palette&quot;">​</a></h3><p>Der Assistent führt durch Auslöser, Bedingungen und Aktionen. In der Palette kannst du suchen und Bausteine zum passenden Abschnitt ziehen.</p><h3 id="ausloser" tabindex="-1">Auslöser <a class="header-anchor" href="#ausloser" aria-label="Permalink to &quot;Auslöser&quot;">​</a></h3><p>Ein Auslöser startet die Regel. Wähle Zustand mit Von/Nach, Attribut und Mindestdauer, Zahlenschwelle, Uhrzeit, Helferuhrzeit, Sonne mit Versatz, MQTT, HA-Ereignis oder HA-Start. Bereich und Label fassen ausgewählte Entitäten zusammen.</p><h3 id="bedingungen" tabindex="-1">Bedingungen <a class="header-anchor" href="#bedingungen" aria-label="Permalink to &quot;Bedingungen&quot;">​</a></h3><p>Prüfe Zustand, Zahlenwert, Attribut, Uhrzeit oder Wochentag. UND verlangt alle Prüfungen, ODER mindestens eine, NICHT kehrt die Prüfung um.</p><h3 id="ausgelost-durch" tabindex="-1">Ausgelöst durch <a class="header-anchor" href="#ausgelost-durch" aria-label="Permalink to &quot;Ausgelöst durch&quot;">​</a></h3><p>Gib Auslösern IDs wie <code>first</code> und <code>second</code>. Prüfe die ID unter UND. Damit entscheidet dieselbe Regel je nach Auslöser zwischen DANN und SONST.</p><h3 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h3><p>Im Expertenmodus kannst du eine native HA-Template-Bedingung eingeben. Ihr Ergebnis entscheidet, ob die Bedingung erfüllt ist.</p><h3 id="aktionen-und-zweige" tabindex="-1">Aktionen und Zweige <a class="header-anchor" href="#aktionen-und-zweige" aria-label="Permalink to &quot;Aktionen und Zweige&quot;">​</a></h3><p>Füge mehrere Aktionen in der gewünschten Reihenfolge ein. Wähle Ziel und Parameter oder nutze Verzögerung, Warten auf Zustand, Skriptaufruf oder Benachrichtigung.</p><h3 id="yaml-und-rules-json" tabindex="-1">YAML und Rules-JSON <a class="header-anchor" href="#yaml-und-rules-json" aria-label="Permalink to &quot;YAML und Rules-JSON&quot;">​</a></h3><p>YAML ist für Home Assistant. Rules-JSON als Text oder Datei kannst du wieder im Rules-Editor öffnen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn ein Schwellenwert-Auslöser nur einmal feuert, bringe den Wert erst wieder aus dem Schwellenbereich und anschließend erneut hinein.</p>',22)])])}const f=t(r,[["render",u]]);export{m as __pageData,f as default};
